export const isSl = (s: string) => {
  const p = s.replace(/[\u064B-\u065F\u0670\u0640]/g, "").replace(/[أإآ]/g, "ا");
  return p === "اللهم صل وسلم وبارك عليه" || (p.length < 110 && p.indexOf("اللهم صل وسلم اشرف الصلاة") === 0);
};

