            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "وَكُلُّ مَنْ لِلنَّبِيِّ يَصْحَبُ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "وَاغْفِرْ وَسَامِحْ مَنْ كَانَ أَذْنَبَ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "وَبَلِّغِ الْكُلَّ كُلَّ مَطْلَبِ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "وَاسْلُكْ بِنَا رَبِّ خَيْرَ مَذْهَبِ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "وَأَصْلِحْ وَسَهِّلْ مَا قَدْ تَصَعَّبَ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "أَعْلَى الْبَرَايَا جَاهًا وَأَرْحَبُ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "أَصْدَقِ عَبْدٍ بِالْحَقِّ أَعْرَبَ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "خَيْرِ الْوَرَى مَنْهَجًا وَأَصْوَبَ"],
            ["يَا رَبِّ صَلِّ عَلَى مُحَمَّدٍ", "مَا طَيْرُ يُمْنٍ غَنَّى فَاطْرَبِ"]
